    Tensor decompress(const Tensor& input) override {
        return zfp_decompress(input);
    }
};

class PipeAlltoAll : public AbsAlltoAll {
    void all_to_all(const Tensor& input, Tensor& output, size_t size) override {
        // 使用两个 CUDA stream 并发执行 intra/inter SR
        launch_intra_stream(input, output, size);
        launch_inter_stream(input, output, size);
        sync_both_streams();
